# ==============================================================
# CARD_REQUEST.PER
# Module : Demande de carte bancaire
# IHM    : Genero Web
# ==============================================================

LAYOUT
(
  GRID
  {
    [f01                                  ]
    [f02                                  ]

    [f03        ][f04                     ]
    [f05        ][f06                     ]
    [f07        ][f08                     ]

    [f09        ][f10                     ]
    [f11        ][f12                     ]
    [f13        ][f14                     ]

    [f15        ][f16                     ]
    [f17        ][f18                     ]

    [f19                                  ]
    [f20                                  ]

    [f21        ][f22        ][f23        ]
  }
)

ATTRIBUTES

GROUPBOX f01 = GROUP "Informations du compte";

LABEL f02 = "Agence";

EDIT f03 = v_agency,
    REQUIRED;

LABEL f04 = "Numéro de compte";

EDIT f05 = v_account,
    REQUIRED;

LABEL f06 = "Devise";

COMBOBOX f07 = v_currency,
    ITEMS (
        "XOF",
        "EUR",
        "USD"
    ),
    REQUIRED;

BUTTON f08 = "Rechercher",
    ACTION search_account;


/*
 * --------------------------------------------------------------
 * INFORMATIONS CLIENT
 * --------------------------------------------------------------
 */

GROUPBOX f09 = GROUP "Informations client";

LABEL f10 = "Nom";

EDIT f11 = v_last_name,
    REQUIRED;

LABEL f12 = "Prénom";

EDIT f13 = v_first_name,
    REQUIRED;

LABEL f14 = "Téléphone";

EDIT f15 = v_phone,
    REQUIRED;

LABEL f16 = "Email";

EDIT f17 = v_email;

LABEL f18 = "N° pièce d'identité";

EDIT f19 = v_identity_number,
    REQUIRED;

LABEL f20 = "Type de compte";

COMBOBOX f21 = v_account_type,
    ITEMS (
        "COURANT",
        "EPARGNE",
        "PROFESSIONNEL"
    );


/*
 * --------------------------------------------------------------
 * INFORMATIONS CARTE
 * --------------------------------------------------------------
 */

GROUPBOX f22 = GROUP "Informations carte";

LABEL f23 = "Type de carte";

COMBOBOX f24 = v_card_type,
    ITEMS (
        "VISA_CLASSIC",
        "VISA_GOLD",
        "VISA_PREMIUM",
        "MASTERCARD_STANDARD",
        "MASTERCARD_GOLD"
    ),
    REQUIRED;

LABEL f25 = "Tarif";

EDIT f26 = v_tariff,
    READONLY;

LABEL f27 = "Devise tarif";

COMBOBOX f28 = v_tariff_currency,
    ITEMS (
        "XOF",
        "EUR",
        "USD"
    ),
    REQUIRED;


/*
 * --------------------------------------------------------------
 * INFORMATIONS DEMANDE
 * --------------------------------------------------------------
 */

GROUPBOX f29 = GROUP "Informations de la demande";

LABEL f30 = "Date de demande";

EDIT f31 = v_request_date,
    READONLY;

LABEL f32 = "Motif";

EDIT f33 = v_reason;

LABEL f34 = "Statut";

EDIT f35 = v_status,
    READONLY;


/*
 * --------------------------------------------------------------
 * OBSERVATIONS
 * --------------------------------------------------------------
 */

LABEL f36 = "Observations";

TEXTEDIT f37 = v_comment;


/*
 * --------------------------------------------------------------
 * ACTIONS
 * --------------------------------------------------------------
 */

BUTTON f38 = "Enregistrer",
    ACTION save_request;

BUTTON f39 = "Annuler",
    ACTION cancel_request;

BUTTON f40 = "Quitter",
    ACTION close_form;

